{
  "name": "preventio",
  "version": "0.1.0",
  "description": "Cross-platform keep-awake utility with Claude Code auto-activation.",
  "type": "module",
  "bin": {
    "preventio": "dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "tsc",
    "prepare": "npm run build",
    "test": "npm run build && node --test",
    "start": "npm run build && node dist/cli.js start"
  },
  "keywords": [
    "keep-awake",
    "caffeine",
    "no-sleep",
    "prevent-sleep",
    "insomnia",
    "claude-code",
    "cross-platform"
  ],
  "author": "Hikhakk",
  "license": "MIT",
  "dependencies": {
    "systray2": "^2.0.3"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "typescript": "^5.7.0"
  }
}

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { join, dirname } from "node:path";

const SETTINGS_FILE = join(homedir(), ".claude", "settings.json");

const EVENTS_PLAIN = ["SessionStart", "UserPromptSubmit", "Stop", "SessionEnd"];
const EVENTS_MATCHED = ["PreToolUse", "PostToolUse"];
const ALL_EVENTS = [...EVENTS_PLAIN, ...EVENTS_MATCHED];

type HookCommand = { type: "command"; command: string; timeout?: number };
type HookEntry = { matcher?: string; hooks: HookCommand[] };
type Settings = { hooks?: Record<string, HookEntry[]>; [k: string]: unknown };

function command(cliPath: string, event: string): string {
  return `"${process.execPath}" "${cliPath}" hook ${event}`;
}

function isOurs(entry: HookEntry): boolean {
  return (
    Array.isArray(entry?.hooks) &&
    entry.hooks.some(
      (h) =>
        typeof h?.command === "string" &&
        h.command.includes(" hook ") &&
        (h.command.includes("preventio") || h.command.includes("cli.js")),
    )
  );
}

function readSettings(): Settings {
  if (!existsSync(SETTINGS_FILE)) return {};
  try {
    return JSON.parse(readFileSync(SETTINGS_FILE, "utf8")) as Settings;
  } catch (err) {
    throw new Error(
      `Could not parse ${SETTINGS_FILE} as JSON (${String(err)}). ` +
        `Fix or remove it, then retry.`,
    );
  }
}

function writeSettings(settings: Settings): void {
  mkdirSync(dirname(SETTINGS_FILE), { recursive: true });
  writeFileSync(SETTINGS_FILE, JSON.stringify(settings, null, 2) + "\n");
}

export function installHooks(cliPath: string): void {
  const settings = readSettings();
  settings.hooks ??= {};
  for (const event of ALL_EVENTS) {
    const existing = Array.isArray(settings.hooks[event])
      ? settings.hooks[event]
      : [];
    const cleaned = existing.filter((e) => !isOurs(e));
    const hookCmd: HookCommand = {
      type: "command",
      command: command(cliPath, event),
      timeout: 10,
    };
    const entry: HookEntry = EVENTS_MATCHED.includes(event)
      ? { matcher: "*", hooks: [hookCmd] }
      : { hooks: [hookCmd] };
    cleaned.push(entry);
    settings.hooks[event] = cleaned;
  }
  writeSettings(settings);
  console.log(`Installed Preventio hooks into ${SETTINGS_FILE}`);
  console.log("Claude Code will now keep this machine awake during sessions.");
}

export function uninstallHooks(): void {
  const settings = readSettings();
  if (!settings.hooks) {
    console.log("No Preventio hooks found.");
    return;
  }
  for (const event of Object.keys(settings.hooks)) {
    const list = settings.hooks[event];
    if (!Array.isArray(list)) continue;
    const cleaned = list.filter((e) => !isOurs(e));
    if (cleaned.length > 0) settings.hooks[event] = cleaned;
    else delete settings.hooks[event];
  }
  if (Object.keys(settings.hooks).length === 0) delete settings.hooks;
  writeSettings(settings);
  console.log("Removed Preventio hooks.");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Redirect the state dir into a throwaway HOME before importing the module.
const tmp = mkdtempSync(join(tmpdir(), "preventio-test-"));
process.env.HOME = tmp;
process.env.USERPROFILE = tmp;

const {
  addHold,
  removeHold,
  removeHoldsByPrefix,
  listHolds,
  reap,
  isExpired,
  shouldInhibit,
  activeReason,
} = await import("../dist/core/holds.js");

const MIN = 60_000;

test("add/remove a manual hold flips shouldInhibit", () => {
  const now = 1_000_000;
  assert.equal(shouldInhibit(listHolds(), now), false);

  addHold("manual", "manual", now);
  assert.equal(listHolds().length, 1);
  assert.equal(shouldInhibit(listHolds(), now), true);
  assert.equal(activeReason(listHolds(), now), "manual");

  removeHold("manual", "manual");
  assert.equal(listHolds().length, 0);
  assert.equal(shouldInhibit(listHolds(), now), false);
  assert.equal(activeReason(listHolds(), now), null);
});

test("session leases expire after 30 minutes and are reaped", () => {
  const t0 = 2_000_000;
  addHold("session", "s1", t0);

  assert.equal(isExpired(listHolds()[0], t0 + 29 * MIN), false);
  assert.equal(isExpired(listHolds()[0], t0 + 31 * MIN), true);
  assert.equal(activeReason(listHolds(), t0 + 5 * MIN), "claude");

  reap(t0 + 31 * MIN);
  assert.equal(listHolds().length, 0);
});

test("tool holds survive long runs but can be removed explicitly", () => {
  const t0 = 3_000_000;
  addHold("tool", "s2:Bash", t0);

  // Still active an hour into a long, input-less tool call.
  assert.equal(shouldInhibit(listHolds(), t0 + 60 * MIN), true);
  reap(t0 + 60 * MIN);
  assert.equal(listHolds().length, 1);

  removeHold("tool", "s2:Bash");
  assert.equal(listHolds().length, 0);
});

test("removeHoldsByPrefix clears a session's tool holds", () => {
  const t0 = 4_000_000;
  addHold("tool", "sess:Bash", t0);
  addHold("tool", "sess:Read", t0);
  addHold("tool", "other:Bash", t0);

  removeHoldsByPrefix("tool", "sess:");
  const ids = listHolds().map((h) => h.id);
  assert.deepEqual(ids, ["other:Bash"]);

  removeHold("tool", "other:Bash");
  assert.equal(listHolds().length, 0);
});

import { watch, FSWatcher } from "node:fs";
import { Inhibitor } from "./core/inhibitor.js";
import {
  listHolds,
  reap,
  shouldInhibit,
  activeReason,
  addHold,
  removeHold,
} from "./core/holds.js";
import {
  readConfig,
  writeConfig,
  writeStatus,
  writePid,
  removePid,
  daemonRunning,
} from "./core/state.js";
import { HOLDS_DIR, CONFIG_FILE, ensureDirs } from "./core/paths.js";
import { initTray, type TrayHandle } from "./tray.js";

export async function runDaemon({
  withTray,
}: {
  withTray: boolean;
}): Promise<void> {
  if (daemonRunning()) {
    console.error("[preventio] daemon already running");
    return;
  }
  ensureDirs();
  writePid(process.pid);

  // A misbehaving tray must never take the daemon down with it.
  process.on("unhandledRejection", (err) =>
    console.error(`[preventio] unhandled rejection: ${String(err)}`),
  );

  const inhibitor = new Inhibitor();
  let tray: TrayHandle | null = null;

  let debounce: NodeJS.Timeout | null = null;
  const scheduleRecompute = () => {
    if (debounce) return;
    debounce = setTimeout(() => {
      debounce = null;
      recompute();
    }, 100);
  };

  function recompute() {
    const now = Date.now();
    reap(now);
    const holds = listHolds();
    const cfg = readConfig();
    const inhibit = shouldInhibit(holds, now);
    inhibitor.apply(inhibit, cfg.keepDisplay);
    const status = {
      inhibiting: inhibit,
      reason: activeReason(holds, now),
      keepDisplay: cfg.keepDisplay,
      holdCount: holds.length,
      holds: holds.map((h) => ({ type: h.type, id: h.id })),
      updatedAt: now,
      pid: process.pid,
    };
    writeStatus(status);
    tray?.render(status);
  }

  const watchers: FSWatcher[] = [];
  try {
    watchers.push(watch(HOLDS_DIR, scheduleRecompute));
  } catch {
    // fall back to the interval below
  }
  try {
    watchers.push(watch(CONFIG_FILE, scheduleRecompute));
  } catch {
    // config file may not exist yet; interval + SIGHUP cover it
  }

  const interval = setInterval(recompute, 60_000);

  let shuttingDown = false;
  function shutdown() {
    if (shuttingDown) return;
    shuttingDown = true;
    clearInterval(interval);
    if (debounce) clearTimeout(debounce);
    for (const w of watchers) {
      try {
        w.close();
      } catch {
        // ignore
      }
    }
    inhibitor.stop();
    tray?.destroy();
    removePid();
    process.exit(0);
  }

  if (withTray) {
    tray = await initTray({
      onToggleManual: () => {
        const hasManual = listHolds().some((h) => h.type === "manual");
        if (hasManual) removeHold("manual", "manual");
        else addHold("manual", "manual");
        recompute();
      },
      onToggleDisplay: () => {
        writeConfig({ keepDisplay: !readConfig().keepDisplay });
        recompute();
      },
      onQuit: shutdown,
    });
  }

  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
  process.on("SIGHUP", recompute);

  recompute();
  console.error(
    `[preventio] daemon started (pid ${process.pid}, ${
      tray ? "tray" : "headless"
    })`,
  );

  // Keep the process alive (the interval already does this; this is belt-and-suspenders).
  await new Promise<never>(() => {});
}

#!/usr/bin/env node
import { parseArgs } from "node:util";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import {
  addHold,
  removeHold,
  removeHoldsByPrefix,
  listHolds,
  type HoldType,
} from "./core/holds.js";
import {
  writeConfig,
  readConfig,
  readStatus,
  daemonRunning,
  readPid,
  isAlive,
} from "./core/state.js";
import { runDaemon } from "./daemon.js";
import { installHooks, uninstallHooks } from "./hooks/install.js";
import { installService, uninstallService } from "./service.js";

const CLI_PATH = fileURLToPath(import.meta.url);

function ensureDaemon(): void {
  if (daemonRunning()) return;
  // Start with the tray; it degrades to headless automatically where there's no
  // GUI session, so whichever instance wins the race still shows a menu-bar icon.
  const child = spawn(process.execPath, [CLI_PATH, "start"], {
    detached: true,
    stdio: "ignore",
  });
  child.unref();
}

function nudgeDaemon(): void {
  const pid = readPid();
  if (pid && isAlive(pid)) {
    try {
      process.kill(pid, "SIGHUP");
    } catch {
      // best effort
    }
  }
}

function readStdin(): Promise<string> {
  return new Promise((resolve) => {
    if (process.stdin.isTTY) return resolve("");
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (c) => (data += c));
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", () => resolve(data));
  });
}

function printStatus(): void {
  const status = readStatus();
  const pid = readPid();
  const running = pid !== null && isAlive(pid);
  if (!status) {
    console.log(
      `Preventio: daemon ${running ? "running" : "not running"}, ${
        listHolds().length
      } hold(s).`,
    );
    return;
  }
  console.log(
    `Preventio: ${status.inhibiting ? "AWAKE" : "idle (sleep allowed)"}${
      status.reason ? ` — ${status.reason}` : ""
    }`,
  );
  console.log(`  daemon:        ${running ? `running (pid ${pid})` : "stopped"}`);
  console.log(`  keep screen:   ${status.keepDisplay ? "on" : "off"}`);
  console.log(`  active holds:  ${status.holdCount}`);
  for (const h of status.holds) {
    console.log(`    - ${h.type}: ${h.id}`);
  }
}

async function handleHook(event: string | undefined): Promise<void> {
  const raw = await readStdin();
  let data: { session_id?: string; tool_name?: string } = {};
  try {
    data = JSON.parse(raw);
  } catch {
    // hook may be invoked without payload; fall through with defaults
  }
  const session = data.session_id ?? "unknown";
  const tool = data.tool_name ?? "tool";

  switch (event) {
    case "SessionStart":
    case "UserPromptSubmit":
    case "Stop":
      addHold("session", session);
      ensureDaemon();
      break;
    case "PreToolUse":
      addHold("tool", `${session}:${tool}`);
      ensureDaemon();
      break;
    case "PostToolUse":
      removeHold("tool", `${session}:${tool}`);
      break;
    case "SessionEnd":
      removeHold("session", session);
      removeHoldsByPrefix("tool", `${session}:`);
      break;
  }
  process.exit(0);
}

function help(): void {
  console.log(`Preventio — keep your machine awake.

Usage:
  preventio start [--no-tray]   Start the daemon (with menu-bar tray by default)
  preventio stop                Stop the daemon
  preventio on                  Keep awake now (manual hold)
  preventio off                 Release the manual hold
  preventio status              Show current state
  preventio keepdisplay on|off  Also keep the screen on (or not)
  preventio install-hooks       Auto-keep-awake while Claude Code runs
  preventio uninstall-hooks     Remove the Claude Code hooks
  preventio install-service     Start Preventio automatically at login
  preventio uninstall-service   Remove the login service

Low-level (used by hooks):
  preventio hold add|remove --type <session|tool> --id <id>
  preventio hook <EventName>    Reads hook JSON from stdin`);
}

async function main(): Promise<void> {
  const { positionals, values } = parseArgs({
    allowPositionals: true,
    options: {
      "no-tray": { type: "boolean" },
      type: { type: "string" },
      id: { type: "string" },
    },
  });
  const [command, sub] = positionals;

  switch (command) {
    case "start":
      await runDaemon({ withTray: !values["no-tray"] });
      break;
    case "on":
      addHold("manual", "manual");
      ensureDaemon();
      console.log("Keep-awake ON (manual).");
      break;
    case "off":
      removeHold("manual", "manual");
      nudgeDaemon();
      console.log("Manual hold released.");
      break;
    case "stop": {
      const pid = readPid();
      if (pid && isAlive(pid)) {
        try {
          process.kill(pid, "SIGTERM");
          console.log(`Stopped daemon (pid ${pid}).`);
        } catch (err) {
          console.error(`Could not stop daemon: ${String(err)}`);
        }
      } else {
        console.log("Daemon not running.");
      }
      break;
    }
    case "status":
      printStatus();
      break;
    case "keepdisplay": {
      const enabled = sub === "on";
      writeConfig({ ...readConfig(), keepDisplay: enabled });
      ensureDaemon();
      nudgeDaemon();
      console.log(`Keep screen on: ${enabled ? "on" : "off"}.`);
      break;
    }
    case "hold": {
      const type = values.type as HoldType | undefined;
      const id = values.id;
      if (!type || !id) {
        console.error("hold requires --type and --id");
        process.exit(1);
      }
      if (sub === "add") {
        addHold(type, id);
        ensureDaemon();
      } else if (sub === "remove") {
        removeHold(type, id);
      } else {
        console.error("hold expects 'add' or 'remove'");
        process.exit(1);
      }
      break;
    }
    case "hook":
      await handleHook(sub);
      break;
    case "install-hooks":
      installHooks(CLI_PATH);
      break;
    case "uninstall-hooks":
      uninstallHooks();
      break;
    case "install-service":
      installService(CLI_PATH);
      break;
    case "uninstall-service":
      uninstallService();
      break;
    default:
      help();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { createRequire } from "node:module";
import { chmodSync, existsSync, readdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { trayIcon } from "./core/icon.js";
import type { Status } from "./core/state.js";

/**
 * systray2 ships its Go helper binaries without the execute bit, and the copy
 * it places in ~/.cache inherits that — so the very first launch fails with
 * EACCES. Make the relevant binaries executable before we start the tray.
 */
function ensureTrayBinaryExecutable(): void {
  if (process.platform === "win32") return; // .exe needs no chmod
  const bin =
    process.platform === "darwin"
      ? "tray_darwin_release"
      : "tray_linux_release";
  const chmod = (file: string) => {
    try {
      if (existsSync(file)) chmodSync(file, 0o755);
    } catch {
      // best effort
    }
  };
  try {
    const require = createRequire(import.meta.url);
    const pkgDir = dirname(require.resolve("systray2/package.json"));
    chmod(join(pkgDir, "traybin", bin));
  } catch {
    // systray2 not resolvable from here
  }
  try {
    const cacheRoot = join(homedir(), ".cache", "node-systray");
    for (const version of readdirSync(cacheRoot)) {
      chmod(join(cacheRoot, version, bin));
    }
  } catch {
    // no cache dir yet
  }
}

export interface TrayHandlers {
  onToggleManual(): void;
  onToggleDisplay(): void;
  onQuit(): void;
}

export interface TrayHandle {
  render(status: Status): void;
  destroy(): void;
}

const IDX_STATUS = 0;
const IDX_MANUAL = 1;
const IDX_DISPLAY = 2;
const IDX_QUIT = 4; // index 3 is the separator

function statusTitle(status: Status): string {
  if (!status.inhibiting) return "Idle — sleep allowed";
  if (status.reason === "manual") return "Awake — manual";
  return "Awake — Claude Code";
}

/**
 * Start the menu-bar / system-tray icon. Returns null (and logs) if the tray
 * can't be created — the daemon then keeps running headless.
 */
export async function initTray(
  handlers: TrayHandlers,
): Promise<TrayHandle | null> {
  let SysTray: any;
  try {
    const mod: any = await import("systray2");
    // systray2 is CJS compiled from `export default`, so under ESM the class
    // lands at mod.default.default; fall back through the other shapes.
    SysTray = mod.default?.default ?? mod.default ?? mod;
  } catch (err) {
    console.error(`[preventio] tray unavailable (systray2 not loaded): ${String(err)}`);
    return null;
  }

  ensureTrayBinaryExecutable();

  const icon = trayIcon();

  const items = [
    { title: "Idle — sleep allowed", tooltip: "", checked: false, enabled: false },
    { title: "Keep awake (manual)", tooltip: "Toggle manual keep-awake", checked: false, enabled: true },
    { title: "Also keep screen on", tooltip: "Prevent the display from sleeping too", checked: false, enabled: true },
    SysTray.separator,
    { title: "Quit", tooltip: "Stop Preventio", checked: false, enabled: true },
  ];

  let systray: any;
  try {
    systray = new SysTray({
      menu: {
        icon: icon.base64,
        isTemplateIcon: icon.isTemplate,
        title: "",
        tooltip: "Preventio",
        items,
      },
      debug: false,
      copyDir: true,
    });
  } catch (err) {
    console.error(`[preventio] tray failed to start: ${String(err)}`);
    return null;
  }

  // Wait for the helper process to come up before sending it anything.
  try {
    await Promise.race([
      systray.ready(),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error("tray ready timed out")), 5000),
      ),
    ]);
  } catch (err) {
    console.error(`[preventio] tray did not become ready: ${String(err)}`);
    try {
      systray.kill(false);
    } catch {
      // ignore
    }
    return null;
  }

  if (typeof systray.onError === "function") {
    systray.onError((err: unknown) =>
      console.error(`[preventio] tray error: ${String(err)}`),
    );
  }

  systray.onClick((action: any) => {
    try {
      switch (action.seq_id) {
        case IDX_MANUAL:
          handlers.onToggleManual();
          break;
        case IDX_DISPLAY:
          handlers.onToggleDisplay();
          break;
        case IDX_QUIT:
          handlers.onQuit();
          break;
      }
    } catch (err) {
      console.error(`[preventio] tray click error: ${String(err)}`);
    }
  });

  const update = (index: number, patch: Record<string, unknown>) => {
    const item = { ...items[index], ...patch };
    items[index] = item;
    try {
      const result = systray.sendAction({
        type: "update-item",
        item,
        seq_id: index,
      });
      // sendAction is async; swallow rejections so a tray hiccup never crashes us
      if (result && typeof result.catch === "function") result.catch(() => {});
    } catch {
      // tray may be shutting down
    }
  };

  return {
    render(status: Status) {
      update(IDX_STATUS, { title: statusTitle(status) });
      update(IDX_MANUAL, { checked: status.reason === "manual" });
      update(IDX_DISPLAY, { checked: status.keepDisplay });
    },
    destroy() {
      try {
        systray.kill(false);
      } catch {
        // ignore
      }
    },
  };
}

import {
  writeFileSync,
  mkdirSync,
  existsSync,
  unlinkSync,
  realpathSync,
} from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { execFileSync } from "node:child_process";
import { readPid, isAlive } from "./core/state.js";

const LABEL = "com.preventio.daemon";

/**
 * Stop whatever daemon is currently recorded in the pid file — including an
 * orphan one a Claude Code hook may have spawned — so the service manager can
 * own a single clean instance.
 */
function stopExistingDaemon(): void {
  const pid = readPid();
  if (pid && isAlive(pid)) {
    try {
      process.kill(pid, "SIGTERM");
    } catch {
      // already gone or not ours
    }
  }
}

/** Absolute node path, preferring a stable Homebrew symlink over a version-pinned Cellar path. */
function nodePath(): string {
  const exec = process.execPath;
  for (const prefix of ["/opt/homebrew", "/usr/local"]) {
    if (exec.startsWith(`${prefix}/Cellar/node/`)) {
      const stable = `${prefix}/bin/node`;
      try {
        realpathSync(stable);
        return stable;
      } catch {
        // symlink missing; fall through
      }
    }
  }
  return exec;
}

function run(cmd: string, args: string[]): void {
  execFileSync(cmd, args, { stdio: "ignore" });
}

// ---------- macOS (LaunchAgent) ----------

function macPlistPath(): string {
  return join(homedir(), "Library", "LaunchAgents", `${LABEL}.plist`);
}

function macPlist(node: string, cli: string, log: string): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>${LABEL}</string>
    <key>ProgramArguments</key>
    <array>
        <string>${node}</string>
        <string>${cli}</string>
        <string>start</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <dict>
        <key>SuccessfulExit</key>
        <false/>
    </dict>
    <key>ProcessType</key>
    <string>Interactive</string>
    <key>StandardOutPath</key>
    <string>${log}</string>
    <key>StandardErrorPath</key>
    <string>${log}</string>
</dict>
</plist>
`;
}

function installMac(node: string, cli: string): string {
  mkdirSync(join(homedir(), "Library", "LaunchAgents"), { recursive: true });
  mkdirSync(join(homedir(), ".preventio"), { recursive: true });
  const plistPath = macPlistPath();
  const log = join(homedir(), ".preventio", "daemon.log");
  writeFileSync(plistPath, macPlist(node, cli, log));

  const uid = process.getuid?.() ?? 0;
  try {
    run("launchctl", ["bootout", `gui/${uid}/${LABEL}`]);
  } catch {
    // not loaded yet
  }
  stopExistingDaemon();
  try {
    run("launchctl", ["bootstrap", `gui/${uid}`, plistPath]);
  } catch {
    run("launchctl", ["load", "-w", plistPath]); // legacy fallback
  }
  try {
    run("launchctl", ["kickstart", "-k", `gui/${uid}/${LABEL}`]);
  } catch {
    // RunAtLoad already started it
  }
  return plistPath;
}

function uninstallMac(): void {
  const plistPath = macPlistPath();
  const uid = process.getuid?.() ?? 0;
  try {
    run("launchctl", ["bootout", `gui/${uid}/${LABEL}`]);
  } catch {
    try {
      run("launchctl", ["unload", "-w", plistPath]);
    } catch {
      // not loaded
    }
  }
  if (existsSync(plistPath)) unlinkSync(plistPath);
}

// ---------- Linux (systemd user unit) ----------

function linuxUnitPath(): string {
  return join(homedir(), ".config", "systemd", "user", "preventio.service");
}

function installLinux(node: string, cli: string): string {
  const dir = join(homedir(), ".config", "systemd", "user");
  mkdirSync(dir, { recursive: true });
  const unitPath = linuxUnitPath();
  // Headless on Linux: a systemd user service usually has no GUI session for a tray.
  writeFileSync(
    unitPath,
    `[Unit]
Description=Preventio keep-awake daemon
After=graphical-session.target

[Service]
Type=simple
ExecStart=${node} ${cli} start --no-tray
Restart=on-failure

[Install]
WantedBy=default.target
`,
  );
  stopExistingDaemon();
  run("systemctl", ["--user", "daemon-reload"]);
  run("systemctl", ["--user", "enable", "--now", "preventio.service"]);
  return unitPath;
}

function uninstallLinux(): void {
  try {
    run("systemctl", ["--user", "disable", "--now", "preventio.service"]);
  } catch {
    // not enabled
  }
  const unitPath = linuxUnitPath();
  if (existsSync(unitPath)) unlinkSync(unitPath);
  try {
    run("systemctl", ["--user", "daemon-reload"]);
  } catch {
    // ignore
  }
}

// ---------- Windows (Startup launcher) ----------

function windowsVbsPath(): string {
  const appData =
    process.env.APPDATA ?? join(homedir(), "AppData", "Roaming");
  return join(
    appData,
    "Microsoft",
    "Windows",
    "Start Menu",
    "Programs",
    "Startup",
    "preventio.vbs",
  );
}

function installWindows(node: string, cli: string): string {
  const vbsPath = windowsVbsPath();
  mkdirSync(join(vbsPath, ".."), { recursive: true });
  const cmd = `"${node}" "${cli}" start`;
  const literal = `"${cmd.replace(/"/g, '""')}"`;
  writeFileSync(
    vbsPath,
    `Set s = CreateObject("WScript.Shell")\r\ns.Run ${literal}, 0, False\r\n`,
  );
  stopExistingDaemon();
  try {
    run("wscript", [vbsPath]); // start now, hidden
  } catch {
    // will start at next login regardless
  }
  return vbsPath;
}

function uninstallWindows(): void {
  const vbsPath = windowsVbsPath();
  if (existsSync(vbsPath)) unlinkSync(vbsPath);
}

// ---------- public API ----------

export function installService(cli: string): void {
  const node = nodePath();
  try {
    let path: string;
    switch (process.platform) {
      case "darwin":
        path = installMac(node, cli);
        break;
      case "linux":
        path = installLinux(node, cli);
        break;
      case "win32":
        path = installWindows(node, cli);
        break;
      default:
        console.error(`Unsupported platform: ${process.platform}`);
        process.exit(1);
    }
    console.log(`Installed Preventio to start at login.`);
    console.log(`  service file: ${path!}`);
    console.log(`  node:         ${node}`);
    console.log(`Run "preventio uninstall-service" to remove it.`);
  } catch (err) {
    console.error(`Failed to install service: ${String(err)}`);
    if (process.platform === "linux") {
      console.error(
        "A systemd user session is required (try `loginctl enable-linger $USER`).",
      );
    }
    process.exit(1);
  }
}

export function uninstallService(): void {
  switch (process.platform) {
    case "darwin":
      uninstallMac();
      break;
    case "linux":
      uninstallLinux();
      break;
    case "win32":
      uninstallWindows();
      break;
    default:
      console.error(`Unsupported platform: ${process.platform}`);
      process.exit(1);
  }
  console.log("Removed Preventio login service.");
}

import { spawn, ChildProcess } from "node:child_process";

/**
 * Owns at most one OS-level "stay awake" child process. Call `apply` with the
 * desired state; the engine starts, stops, or restarts the child as needed.
 *
 *   macOS   -> caffeinate (-i prevent idle sleep, -d also keep display on)
 *   Windows -> PowerShell calling SetThreadExecutionState; the flag is cleared
 *              automatically when the process exits (i.e. when we kill it)
 *   Linux   -> systemd-inhibit blocking sleep/idle while a child sleeps forever
 */
export class Inhibitor {
  private child: ChildProcess | null = null;
  private activeKeepDisplay = false;

  apply(shouldInhibit: boolean, keepDisplay: boolean): void {
    if (!shouldInhibit) {
      this.stop();
      return;
    }
    if (this.child && this.activeKeepDisplay === keepDisplay) return; // already correct
    this.stop();
    this.start(keepDisplay);
  }

  stop(): void {
    if (!this.child) return;
    try {
      this.child.kill();
    } catch {
      // ignore
    }
    this.child = null;
  }

  private start(keepDisplay: boolean): void {
    const [cmd, args] = this.command(keepDisplay);
    try {
      const child = spawn(cmd, args, { stdio: "ignore" });
      child.on("error", (err) => {
        console.error(`[preventio] failed to start "${cmd}": ${err.message}`);
        if (this.child === child) this.child = null;
      });
      child.on("exit", () => {
        if (this.child === child) this.child = null;
      });
      this.child = child;
      this.activeKeepDisplay = keepDisplay;
    } catch (err) {
      console.error(`[preventio] could not inhibit sleep: ${String(err)}`);
    }
  }

  private command(keepDisplay: boolean): [string, string[]] {
    switch (process.platform) {
      case "darwin":
        // -i: prevent idle sleep, -m: prevent disk idle, -w: tie lifetime to us
        return [
          "caffeinate",
          [
            "-i",
            "-m",
            ...(keepDisplay ? ["-d"] : []),
            "-w",
            String(process.pid),
          ],
        ];
      case "win32": {
        const ES_CONTINUOUS = 0x80000000;
        const ES_SYSTEM_REQUIRED = 0x00000001;
        const ES_DISPLAY_REQUIRED = 0x00000002;
        let flags = ES_CONTINUOUS | ES_SYSTEM_REQUIRED;
        if (keepDisplay) flags |= ES_DISPLAY_REQUIRED;
        const script =
          "Add-Type -Name P -Namespace W -MemberDefinition " +
          "'[DllImport(\"kernel32.dll\")] public static extern uint SetThreadExecutionState(uint e);'; " +
          `[W.P]::SetThreadExecutionState([uint32]${flags >>> 0}); ` +
          "while ($true) { Start-Sleep -Seconds 3600 }";
        return [
          "powershell",
          ["-NoProfile", "-NonInteractive", "-WindowStyle", "Hidden", "-Command", script],
        ];
      }
      default:
        // Linux and other systemd-based systems
        return [
          "systemd-inhibit",
          [
            "--what=sleep:idle",
            "--who=preventio",
            "--why=Preventio keep-awake",
            "--mode=block",
            "sleep",
            "infinity",
          ],
        ];
    }
  }
}

import {
  readFileSync,
  writeFileSync,
  existsSync,
  unlinkSync,
} from "node:fs";
import { CONFIG_FILE, STATUS_FILE, PID_FILE, ensureDirs } from "./paths.js";

export interface Config {
  keepDisplay: boolean;
}

export interface Status {
  inhibiting: boolean;
  reason: "manual" | "claude" | null;
  keepDisplay: boolean;
  holdCount: number;
  holds: { type: string; id: string }[];
  updatedAt: number;
  pid: number;
}

export function readConfig(): Config {
  try {
    const cfg = JSON.parse(readFileSync(CONFIG_FILE, "utf8")) as Partial<Config>;
    return { keepDisplay: Boolean(cfg.keepDisplay) };
  } catch {
    return { keepDisplay: false };
  }
}

export function writeConfig(config: Config): void {
  ensureDirs();
  writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 2));
}

export function readStatus(): Status | null {
  try {
    return JSON.parse(readFileSync(STATUS_FILE, "utf8")) as Status;
  } catch {
    return null;
  }
}

export function writeStatus(status: Status): void {
  ensureDirs();
  writeFileSync(STATUS_FILE, JSON.stringify(status, null, 2));
}

export function readPid(): number | null {
  try {
    const pid = parseInt(readFileSync(PID_FILE, "utf8").trim(), 10);
    return Number.isFinite(pid) ? pid : null;
  } catch {
    return null;
  }
}

export function writePid(pid: number): void {
  ensureDirs();
  writeFileSync(PID_FILE, String(pid));
}

export function removePid(): void {
  try {
    unlinkSync(PID_FILE);
  } catch {
    // already gone
  }
}

export function isAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err) {
    return (err as NodeJS.ErrnoException).code === "EPERM";
  }
}

/** Is a daemon already running (and not this process)? */
export function daemonRunning(): boolean {
  const pid = readPid();
  return pid !== null && pid !== process.pid && isAlive(pid);
}

